import os,pty,fcntl,termios,struct,subprocess,time,select,codecs,re
class Terminal:
 def __init__(self,w=100,h=30):
  self.w,self.h=w,h;self.x=self.y=0;self.grid=[[' ']*w for i in range(h)];self.pending='';self.decoder=codecs.getincrementaldecoder('utf-8')('replace')
 def feed(self,data):
  s=self.pending+self.decoder.decode(data);i=0
  while i<len(s):
   c=s[i]
   if c=='\x1b':
    if i+1>=len(s): break
    if s[i+1]=='[':
     m=re.match(r'\x1b\[([0-?]*)([ -/]*)([@-~])',s[i:])
     if not m: break
     a=m[1];code=m[3];n=[int(x or 0) for x in a.split(';')] if not a.startswith('?') else []
     if code in ('H','f'): self.y=(n[0] or 1)-1 if n else 0;self.x=(n[1] or 1)-1 if len(n)>1 else 0
     elif code=='J' and n and n[0]==2:self.grid=[[' ']*self.w for r in range(self.h)]
     elif code=='K':
      if 0<=self.y<self.h:
       start=0 if n and n[0]==2 else self.x;end=self.x+1 if n and n[0]==1 else self.w
       for k in range(start,min(self.w,end)): self.grid[self.y][k]=' '
     elif code=='G':self.x=(n[0] or 1)-1
     elif code=='d':self.y=(n[0] or 1)-1
     elif code=='A':self.y=max(0,self.y-(n[0] or 1))
     elif code=='B':self.y+=n[0] or 1
     elif code=='C':self.x+=n[0] or 1
     elif code=='D':self.x=max(0,self.x-(n[0] or 1))
     i+=len(m[0]);continue
    else:i+=2;continue
   if c=='\n': self.y+=1
   elif c=='\r':self.x=0
   elif c=='\b':self.x=max(0,self.x-1)
   elif ord(c)>=32:
    if self.x>=self.w:self.x=0;self.y+=1
    if self.y>=self.h:self.grid.pop(0);self.grid.append([' ']*self.w);self.y=self.h-1
    if self.y>=0: self.grid[self.y][self.x]=c
    self.x+=1
   i+=1
  self.pending=s[i:]
 def lines(self):return [''.join(x).rstrip() for x in self.grid]
class App:
 def __init__(self,args=(),w=100,h=30,path='/workspace/executable'):
  self.term=Terminal(w,h);self.master,slave=pty.openpty();self.raw=b''
  fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',h,w,0,0))
  def setup():os.setsid();fcntl.ioctl(0,termios.TIOCSCTTY,0)
  self.p=subprocess.Popen([path]+list(args),stdin=slave,stdout=slave,stderr=slave,preexec_fn=setup,env={**os.environ,'TERM':'xterm-256color'})
  os.close(slave);self.read(.065)
 def read(self,delay=.05):
  end=time.monotonic()+delay;out=b''
  while time.monotonic()<end:
   if select.select([self.master],[],[],max(0,end-time.monotonic()))[0]:
    try:b=os.read(self.master,65536)
    except OSError:break
    if not b:break
    out+=b
  self.raw+=out;self.term.feed(out);return out
 def send(self,b,delay=.05):os.write(self.master,b.encode() if isinstance(b,str) else b);return self.read(delay)
 def lines(self):return self.term.lines()
 def text(self):return '\n'.join(self.lines()).rstrip()
