"""Command line parsing and diagnostics for the typing trainer."""
import os
import re
import sys

# name, short name, value label, default, description
OPTIONS = [
    ('n', 'n', '2|3|4|w|file', '2', 'use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file.'),
    ('top', 't', '1-200', 50, 'use the top X ngrams ordered by usage.'),
    ('combi', 'c', '1-200', 2, 'how many different ngrams to use in a single lesson.'),
    ('rep', 'r', 'number', 3, 'how often to repeat *each* different ngram in a lesson.'),
    ('wpm', 'w', 'number', 40, 'the wpm threshold at which the lesson is considered a success.'),
    ('acc', 'a', '0-100', 94, 'the accuracy in percent at which the lesson is considered a success.'),
    ('emu-in', '', 'layout', '', 'your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts.'),
    ('emu-out', '', 'layout', '', 'the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts.'),
    ('show-ortho', '', '', False, 'show keyboard in ortholinear format'),
    ('nokb', '', '', False, 'pass this flag to disable the keyboard layout display.'),
    ('cat', '', '', False, "the most important flag. don't practice alone."),
    ('help', 'h', '', False, 'Print help'),
]
BY_NAME = {o[0]: o for o in OPTIONS}
BY_SHORT = {o[1]: o[0] for o in OPTIONS if o[1]}
NUMBERS = {'top', 'combi', 'rep', 'wpm', 'acc'}


def color_enabled(stream):
    if os.environ.get('CLICOLOR_FORCE', '0') not in ('', '0'):
        return True
