"""Lesson generation, scoring, and terminal presentation."""
import math
import random
import time
from terminal import (Screen, NORMAL, BOLD, GRAY, ITALIC_GRAY, GREEN, RED,
                      cell_width, text_width)

LAYOUTS = {
    'qwerty': ("qwertyuiop[]", "asdfghjkl;'", "zxcvbnm,./"),
    'qwertz': ("qwertzuiopü+", "asdfghjklöä", "yxcvbnm,.-"),
    'azerty': ("azertyuiop^$", "qsdfghjklmù", "wxcvbn,;:!"),
    'dvorak': ("',.pyfgcrl/=", "aoeuidhtns-", ";qjkxbmwvz"),
    'colemak': ("qwfpgjluy;[]", "arstdhneio'", "zxcvbkm,./"),
    'colemakdh': ("qwfpbjluy;[]", "arstgmneio'", "zxcdvkh,./"),
}


def number(value):
    if math.isnan(value) or value <= 0:
        return 0
    return min(2147483647, int(value)) if math.isfinite(value) else 2147483647


class Game:
    def __init__(self, options, words):
        self.options = options
        self.words = words[:options['top']]
        self.rng = random.Random()
        self.target = ''
        self.typed = ''
        self.lesson = 0
        self.passed = self.failed = 0
        self.start = None
        self.hits = self.errors = 0
        self.wpm = []
        self.acc = []
        self.born = time.monotonic()
        source = LAYOUTS.get(options['emu-in'], LAYOUTS['qwerty'])
        self.layout = LAYOUTS.get(options['emu-out'], LAYOUTS['qwerty'])
        self.translation = dict(zip(''.join(source), ''.join(self.layout)))
        self.emulate = bool(options['emu-in'] and options['emu-out'])

    def new_lesson(self):
        if not self.words:
            return False
        block = ''.join(self.rng.choice(self.words) + ' ' for _ in range(self.options['combi']))
        self.target = block * self.options['rep']
        self.typed = ''
        self.start = None
        self.hits = self.errors = 0
        self.lesson += 1
        return True

    def event(self, kind, ch):
        if kind == 'quit':
            return False
        if kind == 'backspace':
            self.typed = self.typed[:-1]
            if not self.typed:
                self.start = None
            return True
        if kind == 'char':
            if self.emulate:
                ch = self.translation.get(ch, ch)
            if not (ch.isalpha() or ch == ' '):
                return True
            if len(self.typed.encode()) >= len(self.target.encode()):
                return True
            if not self.typed:
                self.start = time.monotonic()
            pos = len(self.typed)
            self.hits += 1
            if pos >= len(self.target) or self.target[pos] != ch:
                self.errors += 1
            self.typed += ch
        elif kind == 'enter':
            if len(self.typed.encode()) < len(self.target.encode()):
                if not self.typed:
                    self.start = time.monotonic()
                self.typed += '\n'
        else:
            return True
        if self.typed == self.target:
            elapsed = max(0.000000001, time.monotonic() - (self.start or time.monotonic()))
            speed = len(self.target.replace(' ', '').encode('utf-8')) * 12.0 / elapsed
            accuracy = 100.0 * self.hits / (self.hits + self.errors) if self.hits + self.errors else 0.0
            self.wpm.append(speed)
            self.acc.append(accuracy)
            if speed >= self.options['wpm'] and accuracy >= self.options['acc']:
                self.passed += 1
            else:
                self.failed += 1
            self.new_lesson()
        return True

    def keyboard_rows(self):
        a, b, c = self.layout
        row = lambda s: '│ ' + ' │ '.join(s) + ' │'
        top = '┌' + '───┬' * 11 + '───┐'
        if self.options['show-ortho']:
            mid = '├' + '───┼' * 11 + '───┤'
            bottom = '└' + '───┴' * 11 + '───┘'
            return [top, row(a), mid, row(b + '△'), mid, row(c + '△△'), bottom]
        return [top, row(a), '└┬' + '──┴┬' * 11 + '──┘',
                ' ' + row(b), ' └┬' + '──┴┬' * 10 + '──┘',
                '  ' + row(c), '  └' + '───┴' * 9 + '───┘']

    def cat_rows(self):
        phase = int((time.monotonic() - self.born) / 0.15) % 6
        phase = [0, 1, 2, 3, 2, 1][phase]
        rows = [
            '    /\\_/\\     ',
            '   >(•༝• )<   ',
            '    |    \\    ',
            '    || |  )   ',
            '    ll-l-//   ',
            '/▔▔▔▔▔▔▔▔||▔▔\\',
            '         \\\\   ',
            '          V   ',
        ]
        if phase in (1, 2):
            rows[6] = '          \\\\  '
            rows[7] = '           V  ' if phase == 1 else '            > '
        elif phase == 3:
            rows[5] = '/▔▔▔▔▔▔▔▔\\\\▔▔\\'
            rows[6] = '          \\__>'
            rows[7] = '              '
        return rows

    def screen(self, width, height):
        s = Screen(width, height)
        nokb = self.options['nokb']
        if width < 79 or height < (13 if nokb else 20):
            if nokb:
                lines = ['Please resize your terminal to at least 80x13.', '<esc> or <ctrl-c> to quit']
            else:
                lines = ['Please resize your terminal to at least 80x20,',
                         'or consider disabling the keyboard display with --nokb',
                         '', '<esc> or <ctrl-c> to quit']
            for y, line in enumerate(lines):
                s.put(max(0, (width - len(line)) // 2), y, line)
            return s, None
        total = 13 if nokb else 19
        for y in range(total):
            s.put(0, y, '│' + ' ' * 77 + '│')
        s.put(0, 0, '╭' + '─' * 65 + ' Quit ')
        s.put(72, 0, '<esc> ', (True, False, 4))
        s.put(78, 0, '╮')
        s.put(20, 1, '               ngrrram!', BOLD)
        s.put(43, 1, '   by winterveil', ITALIC_GRAY)
        for y in (2, 4, total - 4):
            s.put(1, y, '─' * 77)
        s.put(0, total - 1, '╰' + '─' * 77 + '╯')
        s.put(5, 3, 'Lesson #' + str(self.lesson))
        good = '✔: ' + str(self.passed) + ', '
        bad = '✘: ' + str(self.failed) + '    '
        x = 78 - text_width(good + bad)
        x = s.put(x, 3, good, GREEN)
        s.put(x, 3, bad, RED)
        # The two lesson rows are centered together; only incorrect keys are
        # repeated in the lower row.
        length = text_width(self.target)
        x = 1 + max(0, (77 - length) // 2)
        mistakes = []
        for i, expected in enumerate(self.target):
            color = -1
            if i < len(self.typed):
                color = 2 if self.typed[i] == expected else 1
                mistakes.append(self.typed[i] if self.typed[i] != expected and self.typed[i] not in '\r\n' else ' ')
            else:
                mistakes.append(' ')
            x = s.put(x, 6, expected, (True, False, color), 78)
        x = 1 + max(0, (77 - text_width(''.join(mistakes))) // 2)
        s.put(x, 7, ''.join(mistakes), ITALIC_GRAY, 78)
        if not nokb:
            x = 6 if self.options['cat'] else 14
            for j, line in enumerate(self.keyboard_rows()):
                s.put(x, 8 + j, line.ljust(78 - x), GRAY, 78)
        avg_wpm = number(sum(self.wpm) / len(self.wpm)) if self.wpm else 0
        avg_acc = number(sum(self.acc) / len(self.acc)) if self.acc else 0
        last_wpm = number(self.wpm[-1]) if self.wpm else 0
        last_acc = number(self.acc[-1]) if self.acc else 0
        def spans(y, segments):
            x = 1
            for text, style in segments:
                x = s.put(x, y, text, style, 78)
        spans(total - 3, [
            ('  need >= %3dWPM,   avg. ' % self.options['wpm'], GRAY),
            ('%3dWPM' % avg_wpm, NORMAL), (',   last', GRAY),
            (' %3dWPM' % last_wpm, NORMAL)])
        spans(total - 2, [
            ('  need >= %3d%% Acc, avg. ' % self.options['acc'], GRAY),
            ('%3d%% Acc' % avg_acc, NORMAL), (', last', GRAY),
            (' %3d%% Acc' % last_acc, NORMAL)])
        if self.options['cat']:
            for j, line in enumerate(self.cat_rows()):
                if 10 + j < total:
                    s.put(61, 10 + j, line.ljust(14), NORMAL, 75)
        cursor = ((39 - len(self.target.encode('utf-8')) // 2 + len(self.typed.encode('utf-8'))) & 65535, 6)
        return s, cursor
