"""Entry point for the independently implemented n-gram typing trainer."""
import errno
import fcntl
import os
import select
import signal
import sys
import termios
import time
import tty

from cli import Parser
from game import Game
from terminal import Display, Keyboard, size
from wordlists import WORDS


def panic(location, message):
    sys.stderr.write("\nthread 'main' (" + str(os.getpid()) + ') panicked at ' + location + ':\n' + message + '\n')
    sys.stderr.write('note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
    sys.stderr.flush()
    raise SystemExit(101)


def io_error(error):
    code = error.errno or 5
    names = {2: 'NotFound', 13: 'PermissionDenied', 22: 'InvalidInput', 32: 'BrokenPipe'}
    kind = names.get(code, 'Uncategorized')
    msg = os.strerror(code).replace('"', '\\"')
    sys.stderr.write('Error: Os { code: ' + str(code) + ', kind: ' + kind + ', message: "' + msg + '" }\n')
    return 1


def vocabulary(n):
    if n in WORDS:
        return WORDS[n]
    if not os.path.isfile(n):
        print('File not found: ' + n)
        raise SystemExit(1)
    try:
        with open(n, 'rb') as f:
            data = f.read()
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        panic('src/ngrams.rs:110:46', 'called `Result::unwrap()` on an `Err` value: Error { kind: InvalidData, message: "stream did not contain valid UTF-8" }')
    except OSError as e:
        kind = 'PermissionDenied' if e.errno == 13 else 'Uncategorized'
        panic('src/ngrams.rs:110:46', 'called `Result::unwrap()` on an `Err` value: Os { code: ' + str(e.errno) + ', kind: ' + kind + ', message: "' + e.strerror + '" }')
    if not text:
        return []
    lines = text.split('\n')
    if lines[-1] == '':
        lines.pop()
    return [word for line in lines for word in (line[:-1] if line.endswith('\r') else line).split(',')]


def main():
    options = Parser(os.path.basename(sys.argv[0]) or 'executable').parse(sys.argv[1:])
    words = vocabulary(options['n'])
    display = Display()
    display.write('\x1b[?1049h')
    terminal_fd = 0
    opened_tty = False
    try:
        if not os.isatty(terminal_fd):
            terminal_fd = os.open('/dev/tty', os.O_RDWR)
            opened_tty = True
        saved = termios.tcgetattr(terminal_fd)
        tty.setraw(terminal_fd, termios.TCSANOW)
        width, height = size(terminal_fd)
    except (OSError, termios.error) as error:
        if not isinstance(error, OSError):
            error = OSError(error.args[0], error.args[1])
        return io_error(error)
    game = Game(options, words)
    keyboard = Keyboard()
    display.clear()
    screen, cursor = game.screen(width, height)
    display.draw(screen, cursor)
    if not game.new_lesson():
        panic('src/game.rs:18:45', 'called `Option::unwrap()` on a `None` value')
    running = True
    resized = [False]
    interrupted = [False]
    signal.signal(signal.SIGWINCH, lambda *args: resized.__setitem__(0, True))
    signal.signal(signal.SIGINT, lambda *args: interrupted.__setitem__(0, True))
    try:
        while running and not interrupted[0]:
            if resized[0]:
                resized[0] = False
                width, height = size(terminal_fd)
                display.clear()
            screen, cursor = game.screen(width, height)
            display.draw(screen, cursor)
            # Input is read from the controlling terminal even if stdin is
            # redirected, just as it is when running in an ordinary shell.
            ready = select.select([terminal_fd], [], [], 0.016)[0]
            if ready:
                data = os.read(terminal_fd, 4096)
                if not data:
                    break
                keyboard.feed(data)
            event = keyboard.next(finish_escape=not ready)
            while event is not None:
                if not game.event(*event):
                    running = False
                    break
                event = keyboard.next()
    except (OSError, termios.error) as error:
        termios.tcsetattr(terminal_fd, termios.TCSANOW, saved)
        display.write('\x1b[?1049l')
        if not isinstance(error, OSError):
            error = OSError(error.args[0], error.args[1])
        return io_error(error)
    termios.tcsetattr(terminal_fd, termios.TCSANOW, saved)
    display.write('\x1b[?1049l')
    if opened_tty:
        os.close(terminal_fd)
    return 0


if __name__ == '__main__':
    sys.exit(main())
