"""Small, dependency-free terminal drawing and keyboard support."""
import errno
import fcntl
import os
import select
import struct
import termios
import tty
import unicodedata

NORMAL = (False, False, -1)
BOLD = (True, False, -1)
GRAY = (False, False, 7)
ITALIC_GRAY = (False, True, 7)
GREEN = (False, False, 2)
RED = (False, False, 1)


def cell_width(ch):
    if not ch or ord(ch[0]) < 32 or ord(ch[0]) == 127:
        return 0
    if unicodedata.combining(ch[0]) or unicodedata.category(ch[0]) in ('Cf', 'Mn', 'Me'):
        return 0
    return 2 if unicodedata.east_asian_width(ch[0]) in ('W', 'F') else 1


def text_width(text):
    return sum(cell_width(ch) for ch in text)


class Screen:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.rows = [[(' ', NORMAL) for _ in range(width)] for _ in range(height)]

    def put(self, x, y, text, style=NORMAL, limit=None):
        if y < 0 or y >= self.height:
            return x
        right = min(self.width, limit) if limit is not None else self.width
        for ch in text:
            w = cell_width(ch)
            if not w:
                if ord(ch) >= 32 and x > 0 and x <= right:
                    old, st = self.rows[y][x - 1]
                    if old:
                        self.rows[y][x - 1] = (old + ch, st)
                continue
            if x + w > right:
                break
            if x >= 0:
                self.rows[y][x] = (ch, style)
                for k in range(1, w):
                    self.rows[y][x + k] = ('', style)
            x += w
        return x


class Display:
    def __init__(self, fd=1):
        self.fd = fd
        self.previous = None

    def clear(self):
        self.previous = None
        self.write('\x1b[2J')

    def write(self, text):
        b = text.encode('utf-8')
        while b:
            try:
                n = os.write(self.fd, b)
            except InterruptedError:
                continue
            b = b[n:]

    def draw(self, screen, cursor):
        out = []
        if self.previous is None or self.previous.width != screen.width or self.previous.height != screen.height:
            previous = Screen(screen.width, screen.height)
        else:
            previous = self.previous
        current_style = NORMAL
        last_pos = None
        for y, row in enumerate(screen.rows):
            old = previous.rows[y]
            for x, cell in enumerate(row):
                if cell == old[x] or not cell[0]:
                    continue
                ch, style = cell
                if last_pos != (x, y):
                    out.append('\x1b[' + str(y + 1) + ';' + str(x + 1) + 'H')
                if style != current_style:
                    b, i, color = style
                    pb, pi, pc = current_style
                    if pb and not b:
                        out.append('\x1b[22m')
                    if pi and not i:
                        out.append('\x1b[23m')
                    if b and not pb:
                        out.append('\x1b[1m')
                    if i and not pi:
                        out.append('\x1b[3m')
                    if color != pc:
                        out.append('\x1b[39m' if color < 0 else '\x1b[38;5;' + str(color) + 'm')
                    current_style = style
                out.append(ch)
                last_pos = (x + text_width(ch), y)
        out.append('\x1b[39m\x1b[49m\x1b[59m\x1b[0m')
        if cursor is None:
            out.append('\x1b[?25l')
        else:
            x, y = cursor
            out.append('\x1b[?25h\x1b[' + str((y & 65535) + 1) + ';' + str((x & 65535) + 1) + 'H')
        self.write(''.join(out))
        self.previous = screen


def size(fd):
    data = fcntl.ioctl(fd, termios.TIOCGWINSZ, b'\0' * 8)
    h, w, _, _ = struct.unpack('HHHH', data)
    return w, h


class Keyboard:
    """Decode the usual terminal key encodings into character or action events."""
    def __init__(self):
        self.buffer = b''
        self.paste = False

    def feed(self, data):
        self.buffer += data

    def next(self, finish_escape=False):
        b = self.buffer
        if not b:
            return None
        if self.paste:
            end = b.find(b'\x1b[201~')
            if end < 0:
                return None
            self.buffer = b[end + 6:]
            self.paste = False
            return ('ignore', '')
        first = b[0]
        if first == 27:
            if len(b) == 1:
                if not finish_escape:
                    return None
                self.buffer = b''
                return ('quit', '')
            if b.startswith(b'\x1b[200~'):
