                return ('ignore', '')
            if b[1] == 79:  # SS3 function or cursor keys
                if len(b) < 3:
                    return None
                self.buffer = b[3:]
                return ('ignore', '')
            # Alt modifies a character without changing its value.
            self.buffer = b[1:]
            return self.next(finish_escape)
        if first < 128:
            self.buffer = b[1:]
            if first == 3:
                return ('quit', '')
            if first in (8, 127):
                return ('backspace', '')
            if first == 13:
                return ('enter', '\n')
            if first in (9, 0):
                return ('ignore', '') if first == 9 else ('char', ' ')
            if 1 <= first <= 26:
                return ('char', chr(first + 96))
            if first in (28, 29, 30, 31):
                return ('char', chr(first + 64))
            return ('char', chr(first))
        n = 2 if first < 224 else 3 if first < 240 else 4
        if len(b) < n:
            return None
        self.buffer = b[n:]
        try:
            return ('char', b[:n].decode('utf-8'))
        except UnicodeDecodeError:
            return ('ignore', '')
